'use client';

/**
 * Generated pictures for typed words, on paid plans.
 *
 * Built-in phrases never come here: they show a bundled symbol or their word
 * (lib/builtInSymbols.ts). What reaches this module is a custom phrase or a
 * predicted word that is not built-in vocabulary. Free and anonymous users see
 * those as words, so no request is made for them at all; paid subscribers get
 * a flat-vector pictogram generated by the Synalux portal.
 *
 * Results are cached in IndexedDB keyed by sha256(cache version + lang + mode +
 * head word). The cache is content-addressed (no user_id in the key) so the
 * same word is generated and stored once per device.
 */

import { PictureMode } from '@/store/settingsStore';
import { SynaluxProfile } from '@/services/aiService';
import { SYNALUX_API, timeoutSignal } from '@/lib/portalConfig';
import { containsProfanity, containsSensitive } from '@/engine/ageBlocklist';

/**
 * Picture mode is derived from the user's Synalux plan, not from a user
 * preference. Free signed-in users get the bundled symbols and see typed
 * words as words; paid subscribers (Standard / Advanced / Enterprise)
 * additionally get generated pictures for typed words.
 *
 * A null profile means anonymous or still loading, so it must stay on the
 * free path. Optimistically calling the paid route caused a burst of 401s for
 * every anonymous first visit. Paid profile hydration changes the mode to
 * `symbols-ai`, which is part of the cache key.
 */
export function pictureModeForProfile(profile: SynaluxProfile | null): PictureMode {
  if (!profile || profile.plan === 'free') return 'symbols';
  return 'symbols-ai';
}

/** Whether a typed word can get a generated picture in this mode. */
export function typedWordPicturesEnabled(mode: PictureMode): boolean {
  return mode === 'symbols-ai';
}

const STYLE_VERSION = 2;
// Part of the cache key. Version 3 started a new database: everything cached
// before it, including third-party pictograms, stays out of the lookup.
const CACHE_VERSION = 3;
const MAX_IMAGE_BYTES = 2 * 1024 * 1024; // 2MB cap — prevents OOM from oversized blobs
// Large enough to hold a full vocabulary board without eviction.
// We do NOT revoke on eviction — a PhraseTile component may still hold
// the old blob URL in its iconUrl state and revoking causes
// WebKitBlobResource error 1. Blob URLs are cleaned up by the browser
// when the page unloads; the memory cost is negligible.
const MAX_MEM_CACHE = 600;
const MISS_CACHE_TTL_MS = 30_000;
const MEM_CACHE = new Map<string, { url: string | null; expiresAt: number }>();
const IN_FLIGHT = new Map<string, Promise<string | null>>();

function memCacheSet(key: string, value: string | null) {
  if (MEM_CACHE.size >= MAX_MEM_CACHE) {
    const oldest = MEM_CACHE.keys().next().value;
    if (oldest !== undefined) MEM_CACHE.delete(oldest);
    // No URL.revokeObjectURL — component may still hold the old URL.
  }
  MEM_CACHE.set(key, { url: value, expiresAt: value ? Infinity : Date.now() + MISS_CACHE_TTL_MS });
}

async function sha256(input: string): Promise<string> {
  const enc = new TextEncoder().encode(input);
  const hash = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function words(phrase: string): string[] {
  return phrase
    .toLowerCase()
    // Keep combining marks: Devanagari, Bengali and Amharic vowel signs are marks, and dropping them turns a listed word
    // into a different, unlisted one (चूतिया -> चतय).
    .replace(/[^\p{L}\p{M}\p{N}\s]/gu, '')
    .trim()
    .split(/\s+/)
    .filter(Boolean);
}

// Tokenize a phrase into the most "iconic" word for the cache key. Picks the
// longest word that isn't a stopword — a heuristic, but good enough for AAC
// vocab where most phrases have a clear head noun/verb ("I want food" → food).
const STOPWORDS = new Set([
  'i', 'me', 'my', 'mine', 'we', 'us', 'our', 'you', 'your',
  'a', 'an', 'the', 'is', 'am', 'are', 'be', 'do', 'does',
  'to', 'of', 'in', 'on', 'at', 'and', 'or', 'but', 'with',
  'for', 'this', 'that', 'these', 'those', 'it', 'its', 'so',
]);
function pickHeadWord(phrase: string): string {
  const all = words(phrase).slice(0, 4);
  if (all.length === 0) return '';
  const content = all.filter((w) => !STOPWORDS.has(w));
  const pool = content.length > 0 ? content : all;
  return pool.reduce((a, b) => (b.length > a.length ? b : a));
}

// ── IndexedDB cache ─────────────────────────────────────────────────────────

const DB_NAME = 'prism-aac-generated-pictures';
const STORE = 'blobs';
let dbPromise: Promise<IDBDatabase> | null = null;

function openDb(): Promise<IDBDatabase> {
  if (typeof window === 'undefined') return Promise.reject(new Error('no window'));
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return dbPromise;
}

async function cacheGet(key: string): Promise<Blob | null> {
  try {
    const db = await openDb();
    return await new Promise<Blob | null>((resolve, reject) => {
      const tx = db.transaction(STORE, 'readonly');
      const req = tx.objectStore(STORE).get(key);
      req.onsuccess = () => resolve((req.result as Blob | undefined) ?? null);
      req.onerror = () => reject(req.error);
    });
  } catch {
    return null;
  }
}

async function cachePut(key: string, blob: Blob): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(blob, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } catch { /* eviction / quota — best effort */ }
}

// ── Cache left by earlier versions ──────────────────────────────────────────

const LEGACY_DB_NAME = 'prism-aac-pictograms';
const LEGACY_MISSES_KEY = 'prism-arasaac-misses';
const LEGACY_CLEARED_KEY = 'prism-legacy-pictograms-cleared';

/**
 * Earlier versions downloaded third-party pictograms and kept them on the
 * device. They are no longer shown; delete them once to free the space.
 * Best effort: a tab still running the old version can hold the database
 * open, in which case the deletion completes when that tab closes.
 */
export function clearLegacyPictogramCache(): void {
  if (typeof window === 'undefined') return;
  try {
    if (localStorage.getItem(LEGACY_CLEARED_KEY)) return;
    localStorage.removeItem(LEGACY_MISSES_KEY);
    const req = indexedDB.deleteDatabase(LEGACY_DB_NAME);
    req.onsuccess = () => {
      try { localStorage.setItem(LEGACY_CLEARED_KEY, '1'); } catch { /* storage full */ }
    };
  } catch { /* storage unavailable (private mode) — nothing to clear */ }
}

// ── Synalux AI ──────────────────────────────────────────────────────────────

async function fetchSynaluxAI(phrase: string, lang: string): Promise<Blob | null> {
  const t = timeoutSignal(5000);
  try {
    const res = await fetch(`${SYNALUX_API}/prism-aac/pictogram`, {
      method: 'POST',
      // 'same-origin': credentials sent to synalux.ai but NOT on cross-origin
      // redirects to supabase.co (which returns ACAO:* — incompatible with
      // credentials:include and triggers a browser CORS block).
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        phrase: phrase.slice(0, 100),
        lang,
        style: 'aac-pictogram',
        styleVersion: STYLE_VERSION,
      }),
      signal: t.signal,
    });
    if (!res.ok) {
      console.warn(`[pictogram] Synalux AI returned ${res.status} for "${phrase}" (${lang})`);
      return null;
    }
    const ct = res.headers.get('content-type') || '';
    if (!ct.startsWith('image/')) {
      console.warn(`[pictogram] Synalux AI returned non-image content-type "${ct}" for "${phrase}"`);
      return null;
    }
    const cl = res.headers.get('content-length');
    if (cl && parseInt(cl, 10) > MAX_IMAGE_BYTES) {
      console.warn(`[pictogram] Synalux AI response too large (${cl} bytes) for "${phrase}"; skipping`);
      return null;
    }
    const blob = await res.blob();
    if (blob.size > MAX_IMAGE_BYTES) {
      console.warn(`[pictogram] Synalux AI blob too large (${blob.size} bytes) for "${phrase}"; skipping`);
      return null;
    }
    return blob;
  } catch (e) {
    console.warn(`[pictogram] Synalux AI fetch failed for "${phrase}":`, e instanceof Error ? e.message : e);
    return null;
  } finally {
    t.cancel();
  }
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * A generated picture for a typed word, or null to show the word.
 *
 * Null without any request when the plan has no generated pictures, and for
 * any phrase containing a word on the profanity or sensitive lists — those
 * are never sent for generation. `shown` is the phrase as the tile shows it
 * and its language, when generation uses another text (the English phrase):
 * a word listed in the shown language blocks the picture too, so Swahili
 * "tako" or Taiwan 幹 never reach generation through an English request.
 */
export async function getPictogramUrl(
  phrase: string,
  lang: string,
  mode: PictureMode,
  shown?: { text: string; lang: string },
): Promise<string | null> {
  if (!typedWordPicturesEnabled(mode)) return null;
  const listed = (text: string, language: string) => containsProfanity(text, language) || containsSensitive(text, language);
  if (listed(phrase, lang) || (shown && listed(shown.text, shown.lang))) return null;
  const token = pickHeadWord(phrase);
  if (!token) return null;

  const key = await sha256(`v${CACHE_VERSION}|${lang}|${mode}|${token}`);
  const existingRequest = IN_FLIGHT.get(key);
  if (existingRequest) return existingRequest;

  const request = resolvePictogramUrl(phrase, lang, key);
  IN_FLIGHT.set(key, request);
  try {
    return await request;
  } finally {
    if (IN_FLIGHT.get(key) === request) IN_FLIGHT.delete(key);
  }
}

async function resolvePictogramUrl(phrase: string, lang: string, key: string): Promise<string | null> {
  const entry = MEM_CACHE.get(key);
  if (entry && Date.now() < entry.expiresAt) return entry.url;
  if (entry) MEM_CACHE.delete(key);

  const cached = await cacheGet(key);
  if (cached) {
    const url = URL.createObjectURL(cached);
    memCacheSet(key, url);
    return url;
  }

  const blob = await fetchSynaluxAI(phrase, lang);
  if (!blob) {
    memCacheSet(key, null);
    return null;
  }
  await cachePut(key, blob);
  const url = URL.createObjectURL(blob);
  memCacheSet(key, url);
  return url;
}
